"use strict";
import { createContext, useContext, useState } from "react";
export const AddLiquidityContext = createContext(null);
export const AddLiquidityProvider = ({ children }) => {
  const [addLiquidityStep, setAddLiquidityStep] = useState("step-1");
  const [stakeStep, setStakeStep] = useState("step-1");
  const [withdrawStep, setWithdrawStep] = useState("step-1");
  return <AddLiquidityContext.Provider
    value={{ setAddLiquidityStep, addLiquidityStep, setStakeStep, stakeStep, setWithdrawStep, withdrawStep }}
  >
      {children}
    </AddLiquidityContext.Provider>;
};
export const useAddLiquidityContext = () => {
  const context = useContext(AddLiquidityContext);
  if (!context) {
    throw new Error("useAddLiquidity must be used within a AddLiquidityProvider");
  }
  return context;
};
